   1: /**
   2:  * Subagent Tool - Delegate tasks to specialized agents
   3:  *
   4:  * Spawns a separate `pi` process for each subagent invocation,
   5:  * giving it an isolated context window.
   6:  *
   7:  * Supports three modes:
   8:  *   - Single: { agent: "name", task: "..." }
   9:  *   - Parallel: { tasks: [{ agent: "name", task: "..." }, ...] }
  10:  *   - Chain: { chain: [{ agent: "name", task: "... {previous} ..." }, ...] }
  11:  *
  12:  * Uses JSON mode to capture structured output from subagents.
  13:  */
  14: 
  15: import { spawn } from "node:child_process";
  16: import * as fs from "node:fs";
  17: import * as os from "node:os";
  18: import * as path from "node:path";
  19: import type { AgentToolResult, ThinkingLevel } from "@earendil-works/pi-agent-core";
  20: import type { Message } from "@earendil-works/pi-ai";
  21: import { StringEnum } from "@earendil-works/pi-ai";
  22: import {
  23: 	CONFIG_DIR_NAME,
  24: 	type ExtensionAPI,
  25: 	getAgentDir,
  26: 	getMarkdownTheme,
  27: 	withFileMutationQueue,
  28: } from "@earendil-works/pi-coding-agent";
  29: import { Container, Markdown, Spacer, Text } from "@earendil-works/pi-tui";
  30: import { Type } from "typebox";
  31: import { type AgentConfig, type AgentScope, discoverAgents } from "./agents.ts";
  32: 
  33: const MAX_PARALLEL_TASKS = 8;
  34: const MAX_CONCURRENCY = 4;
  35: const COLLAPSED_ITEM_COUNT = 10;
  36: const PER_TASK_OUTPUT_CAP = 50 * 1024;
  37: 
  38: function formatTokens(count: number): string {
  39: 	if (count < 1000) return count.toString();
  40: 	if (count < 10000) return `${(count / 1000).toFixed(1)}k`;
  41: 	if (count < 1000000) return `${Math.round(count / 1000)}k`;
  42: 	return `${(count / 1000000).toFixed(1)}M`;
  43: }
  44: 
  45: function formatUsageStats(
  46: 	usage: {
  47: 		input: number;
  48: 		output: number;
  49: 		cacheRead: number;
  50: 		cacheWrite: number;
  51: 		cost: number;
  52: 		contextTokens?: number;
  53: 		turns?: number;
  54: 	},
  55: 	model?: string,
  56: ): string {
  57: 	const parts: string[] = [];
  58: 	if (usage.turns) parts.push(`${usage.turns} turn${usage.turns > 1 ? "s" : ""}`);
  59: 	if (usage.input) parts.push(`↑${formatTokens(usage.input)}`);
  60: 	if (usage.output) parts.push(`↓${formatTokens(usage.output)}`);
  61: 	if (usage.cacheRead) parts.push(`R${formatTokens(usage.cacheRead)}`);
  62: 	if (usage.cacheWrite) parts.push(`W${formatTokens(usage.cacheWrite)}`);
  63: 	if (usage.cost) parts.push(`$${usage.cost.toFixed(4)}`);
  64: 	if (usage.contextTokens && usage.contextTokens > 0) {
  65: 		parts.push(`ctx:${formatTokens(usage.contextTokens)}`);
  66: 	}
  67: 	if (model) parts.push(model);
  68: 	return parts.join(" ");
  69: }
  70: 
  71: function formatToolCall(
  72: 	toolName: string,
  73: 	args: Record<string, unknown>,
  74: 	themeFg: (color: any, text: string) => string,
  75: ): string {
  76: 	const shortenPath = (p: string) => {
  77: 		const home = os.homedir();
  78: 		return p.startsWith(home) ? `~${p.slice(home.length)}` : p;
  79: 	};
  80: 
  81: 	switch (toolName) {
  82: 		case "bash": {
  83: 			const command = (args.command as string) || "...";
  84: 			const preview = command.length > 60 ? `${command.slice(0, 60)}...` : command;
  85: 			return themeFg("muted", "$ ") + themeFg("toolOutput", preview);
  86: 		}
  87: 		case "read": {
  88: 			const rawPath = (args.file_path || args.path || "...") as string;
  89: 			const filePath = shortenPath(rawPath);
  90: 			const offset = args.offset as number | undefined;
  91: 			const limit = args.limit as number | undefined;
  92: 			let text = themeFg("accent", filePath);
  93: 			if (offset !== undefined || limit !== undefined) {
  94: 				const startLine = offset ?? 1;
  95: 				const endLine = limit !== undefined ? startLine + limit - 1 : "";
  96: 				text += themeFg("warning", `:${startLine}${endLine ? `-${endLine}` : ""}`);
  97: 			}
  98: 			return themeFg("muted", "read ") + text;
  99: 		}
 100: 		case "write": {
 101: 			const rawPath = (args.file_path || args.path || "...") as string;
 102: 			const filePath = shortenPath(rawPath);
 103: 			const content = (args.content || "") as string;
 104: 			const lines = content.split("\n").length;
 105: 			let text = themeFg("muted", "write ") + themeFg("accent", filePath);
 106: 			if (lines > 1) text += themeFg("dim", ` (${lines} lines)`);
 107: 			return text;
 108: 		}
 109: 		case "edit": {
 110: 			const rawPath = (args.file_path || args.path || "...") as string;
 111: 			return themeFg("muted", "edit ") + themeFg("accent", shortenPath(rawPath));
 112: 		}
 113: 		case "ls": {
 114: 			const rawPath = (args.path || ".") as string;
 115: 			return themeFg("muted", "ls ") + themeFg("accent", shortenPath(rawPath));
 116: 		}
 117: 		case "find": {
 118: 			const pattern = (args.pattern || "*") as string;
 119: 			const rawPath = (args.path || ".") as string;
 120: 			return themeFg("muted", "find ") + themeFg("accent", pattern) + themeFg("dim", ` in ${shortenPath(rawPath)}`);
 121: 		}
 122: 		case "grep": {
 123: 			const pattern = (args.pattern || "") as string;
 124: 			const rawPath = (args.path || ".") as string;
 125: 			return (
 126: 				themeFg("muted", "grep ") +
 127: 				themeFg("accent", `/${pattern}/`) +
 128: 				themeFg("dim", ` in ${shortenPath(rawPath)}`)
 129: 			);
 130: 		}
 131: 		default: {
 132: 			const argsStr = JSON.stringify(args);
 133: 			const preview = argsStr.length > 50 ? `${argsStr.slice(0, 50)}...` : argsStr;
 134: 			return themeFg("accent", toolName) + themeFg("dim", ` ${preview}`);
 135: 		}
 136: 	}
 137: }
