 249: function getPiInvocation(args: string[]): { command: string; args: string[] } {
 250: 	const currentScript = process.argv[1];
 251: 	const isBunVirtualScript = currentScript?.startsWith("/$bunfs/root/");
 252: 	if (currentScript && !isBunVirtualScript && fs.existsSync(currentScript)) {
 253: 		return { command: process.execPath, args: [currentScript, ...args] };
 254: 	}
 255: 
 256: 	const execName = path.basename(process.execPath).toLowerCase();
 257: 	const isGenericRuntime = /^(node|bun)(\.exe)?$/.test(execName);
 258: 	if (!isGenericRuntime) {
 259: 		return { command: process.execPath, args };
 260: 	}
 261: 
 262: 	return { command: "pi", args };
 263: }
