  38: function formatTokens(count: number): string {
  39: 	if (count < 1000) return count.toString();
  40: 	if (count < 10000) return `${(count / 1000).toFixed(1)}k`;
  41: 	if (count < 1000000) return `${Math.round(count / 1000)}k`;
  42: 	return `${(count / 1000000).toFixed(1)}M`;
  43: }
  44: 
  45: function formatUsageStats(
  46: 	usage: {
  47: 		input: number;
  48: 		output: number;
  49: 		cacheRead: number;
  50: 		cacheWrite: number;
  51: 		cost: number;
  52: 		contextTokens?: number;
  53: 		turns?: number;
  54: 	},
  55: 	model?: string,
  56: ): string {
  57: 	const parts: string[] = [];
  58: 	if (usage.turns) parts.push(`${usage.turns} turn${usage.turns > 1 ? "s" : ""}`);
  59: 	if (usage.input) parts.push(`↑${formatTokens(usage.input)}`);
  60: 	if (usage.output) parts.push(`↓${formatTokens(usage.output)}`);
  61: 	if (usage.cacheRead) parts.push(`R${formatTokens(usage.cacheRead)}`);
  62: 	if (usage.cacheWrite) parts.push(`W${formatTokens(usage.cacheWrite)}`);
  63: 	if (usage.cost) parts.push(`$${usage.cost.toFixed(4)}`);
  64: 	if (usage.contextTokens && usage.contextTokens > 0) {
  65: 		parts.push(`ctx:${formatTokens(usage.contextTokens)}`);
  66: 	}
  67: 	if (model) parts.push(model);
  68: 	return parts.join(" ");
  69: }
