  72: 	toolName: string,
  73: 	args: Record<string, unknown>,
  74: 	themeFg: (color: any, text: string) => string,
  75: ): string {
  76: 	const shortenPath = (p: string) => {
  77: 		const home = os.homedir();
  78: 		return p.startsWith(home) ? `~${p.slice(home.length)}` : p;
  79: 	};
  80: 
  81: 	switch (toolName) {
  82: 		case "bash": {
  83: 			const command = (args.command as string) || "...";
  84: 			const preview = command.length > 60 ? `${command.slice(0, 60)}...` : command;
  85: 			return themeFg("muted", "$ ") + themeFg("toolOutput", preview);
  86: 		}
  87: 		case "read": {
  88: 			const rawPath = (args.file_path || args.path || "...") as string;
  89: 			const filePath = shortenPath(rawPath);
  90: 			const offset = args.offset as number | undefined;
  91: 			const limit = args.limit as number | undefined;
  92: 			let text = themeFg("accent", filePath);
  93: 			if (offset !== undefined || limit !== undefined) {
  94: 				const startLine = offset ?? 1;
  95: 				const endLine = limit !== undefined ? startLine + limit - 1 : "";
  96: 				text += themeFg("warning", `:${startLine}${endLine ? `-${endLine}` : ""}`);
  97: 			}
  98: 			return themeFg("muted", "read ") + text;
  99: 		}
 100: 		case "write": {
 101: 			const rawPath = (args.file_path || args.path || "...") as string;
 102: 			const filePath = shortenPath(rawPath);
 103: 			const content = (args.content || "") as string;
 104: 			const lines = content.split("\n").length;
 105: 			let text = themeFg("muted", "write ") + themeFg("accent", filePath);
 106: 			if (lines > 1) text += themeFg("dim", ` (${lines} lines)`);
 107: 			return text;
 108: 		}
 109: 		case "edit": {
 110: 			const rawPath = (args.file_path || args.path || "...") as string;
 111: 			return themeFg("muted", "edit ") + themeFg("accent", shortenPath(rawPath));
 112: 		}
 113: 		case "ls": {
 114: 			const rawPath = (args.path || ".") as string;
 115: 			return themeFg("muted", "ls ") + themeFg("accent", shortenPath(rawPath));
 116: 		}
 117: 		case "find": {
 118: 			const pattern = (args.pattern || "*") as string;
 119: 			const rawPath = (args.path || ".") as string;
 120: 			return themeFg("muted", "find ") + themeFg("accent", pattern) + themeFg("dim", ` in ${shortenPath(rawPath)}`);
 121: 		}
 122: 		case "grep": {
 123: 			const pattern = (args.pattern || "") as string;
 124: 			const rawPath = (args.path || ".") as string;
 125: 			return (
 126: 				themeFg("muted", "grep ") +
 127: 				themeFg("accent", `/${pattern}/`) +
 128: 				themeFg("dim", ` in ${shortenPath(rawPath)}`)
 129: 			);
 130: 		}
 131: 		default: {
 132: 			const argsStr = JSON.stringify(args);
 133: 			const preview = argsStr.length > 50 ? `${argsStr.slice(0, 50)}...` : argsStr;
 134: 			return themeFg("accent", toolName) + themeFg("dim", ` ${preview}`);
 135: 		}
 136: 	}
 137: }
