 204: type DisplayItem = { type: "text"; text: string } | { type: "toolCall"; name: string; args: Record<string, any> };
 205: 
 206: function getDisplayItems(messages: Message[]): DisplayItem[] {
 207: 	const items: DisplayItem[] = [];
 208: 	for (const msg of messages) {
 209: 		if (msg.role === "assistant") {
 210: 			for (const part of msg.content) {
 211: 				if (part.type === "text") items.push({ type: "text", text: part.text });
 212: 				else if (part.type === "toolCall") items.push({ type: "toolCall", name: part.name, args: part.arguments });
 213: 			}
 214: 		}
 215: 	}
 216: 	return items;
 217: }
