 219: async function mapWithConcurrencyLimit<TIn, TOut>(
 220: 	items: TIn[],
 221: 	concurrency: number,
 222: 	fn: (item: TIn, index: number) => Promise<TOut>,
 223: ): Promise<TOut[]> {
 224: 	if (items.length === 0) return [];
 225: 	const limit = Math.max(1, Math.min(concurrency, items.length));
 226: 	const results: TOut[] = new Array(items.length);
 227: 	let nextIndex = 0;
 228: 	const workers = new Array(limit).fill(null).map(async () => {
 229: 		while (true) {
 230: 			const current = nextIndex++;
 231: 			if (current >= items.length) return;
 232: 			results[current] = await fn(items[current], current);
 233: 		}
 234: 	});
 235: 	await Promise.all(workers);
 236: 	return results;
 237: }
