 265: type OnUpdateCallback = (partial: AgentToolResult<SubagentDetails>) => void;
 266: 
 267: interface DispatchDefaults {
 268: 	model?: string;
 269: 	thinkingLevel?: ThinkingLevel;
 270: }
 271: 
 272: async function runSingleAgent(
 273: 	defaultCwd: string,
 274: 	dispatchDefaults: DispatchDefaults,
 275: 	agents: AgentConfig[],
 276: 	agentName: string,
 277: 	task: string,
 278: 	cwd: string | undefined,
 279: 	step: number | undefined,
 280: 	signal: AbortSignal | undefined,
 281: 	onUpdate: OnUpdateCallback | undefined,
 282: 	makeDetails: (results: SingleResult[]) => SubagentDetails,
 283: ): Promise<SingleResult> {
 284: 	const agent = agents.find((a) => a.name === agentName);
 285: 
 286: 	if (!agent) {
 287: 		const available = agents.map((a) => `"${a.name}"`).join(", ") || "none";
 288: 		return {
 289: 			agent: agentName,
 290: 			agentSource: "unknown",
 291: 			task,
 292: 			exitCode: 1,
 293: 			messages: [],
 294: 			stderr: `Unknown agent: "${agentName}". Available agents: ${available}.`,
 295: 			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
 296: 			step,
 297: 		};
 298: 	}
 299: 
 300: 	const args: string[] = ["--mode", "json", "-p", "--no-session"];
 301: 	const inheritsDispatchConfig = !agent.model;
 302: 	const model = agent.model ?? dispatchDefaults.model;
 303: 	if (model) args.push("--model", model);
 304: 	if (inheritsDispatchConfig && dispatchDefaults.thinkingLevel) {
 305: 		args.push("--thinking", dispatchDefaults.thinkingLevel);
 306: 	}
 307: 	if (agent.tools && agent.tools.length > 0) args.push("--tools", agent.tools.join(","));
 308: 
 309: 	let tmpPromptDir: string | null = null;
 310: 	let tmpPromptPath: string | null = null;
 311: 
 312: 	const currentResult: SingleResult = {
 313: 		agent: agentName,
 314: 		agentSource: agent.source,
 315: 		task,
 316: 		exitCode: 0,
 317: 		messages: [],
 318: 		stderr: "",
 319: 		usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, contextTokens: 0, turns: 0 },
 320: 		model,
 321: 		step,
 322: 	};
 323: 
 324: 	const emitUpdate = () => {
 325: 		if (onUpdate) {
 326: 			onUpdate({
 327: 				content: [{ type: "text", text: getFinalOutput(currentResult.messages) || "(running...)" }],
 328: 				details: makeDetails([currentResult]),
 329: 			});
 330: 		}
 331: 	};
 332: 
 333: 	try {
 334: 		if (agent.systemPrompt.trim()) {
 335: 			const tmp = await writePromptToTempFile(agent.name, agent.systemPrompt);
 336: 			tmpPromptDir = tmp.dir;
 337: 			tmpPromptPath = tmp.filePath;
 338: 			args.push("--append-system-prompt", tmpPromptPath);
 339: 		}
 340: 
 341: 		args.push(`Task: ${task}`);
 342: 		let wasAborted = false;
 343: 
 344: 		const exitCode = await new Promise<number>((resolve) => {
 345: 			const invocation = getPiInvocation(args);
 346: 			const proc = spawn(invocation.command, invocation.args, {
 347: 				cwd: cwd ?? defaultCwd,
 348: 				shell: false,
 349: 				stdio: ["ignore", "pipe", "pipe"],
 350: 			});
 351: 			let buffer = "";
 352: 
 353: 			const processLine = (line: string) => {
 354: 				if (!line.trim()) return;
 355: 				let event: any;
 356: 				try {
 357: 					event = JSON.parse(line);
 358: 				} catch {
 359: 					return;
 360: 				}
 361: 
 362: 				if (event.type === "message_end" && event.message) {
 363: 					const msg = event.message as Message;
 364: 					currentResult.messages.push(msg);
 365: 
 366: 					if (msg.role === "assistant") {
 367: 						currentResult.usage.turns++;
 368: 						const usage = msg.usage;
 369: 						if (usage) {
 370: 							currentResult.usage.input += usage.input || 0;
 371: 							currentResult.usage.output += usage.output || 0;
 372: 							currentResult.usage.cacheRead += usage.cacheRead || 0;
 373: 							currentResult.usage.cacheWrite += usage.cacheWrite || 0;
 374: 							currentResult.usage.cost += usage.cost?.total || 0;
 375: 							currentResult.usage.contextTokens = usage.totalTokens || 0;
 376: 						}
 377: 						if (!currentResult.model && msg.model) currentResult.model = msg.model;
 378: 						if (msg.stopReason) currentResult.stopReason = msg.stopReason;
 379: 						if (msg.errorMessage) currentResult.errorMessage = msg.errorMessage;
 380: 					}
 381: 					emitUpdate();
 382: 				}
 383: 
 384: 				if (event.type === "tool_result_end" && event.message) {
 385: 					currentResult.messages.push(event.message as Message);
 386: 					emitUpdate();
 387: 				}
 388: 			};
 389: 
 390: 			proc.stdout.on("data", (data) => {
 391: 				buffer += data.toString();
 392: 				const lines = buffer.split("\n");
 393: 				buffer = lines.pop() || "";
 394: 				for (const line of lines) processLine(line);
 395: 			});
 396: 
 397: 			proc.stderr.on("data", (data) => {
 398: 				currentResult.stderr += data.toString();
 399: 			});
 400: 
 401: 			proc.on("close", (code) => {
 402: 				if (buffer.trim()) processLine(buffer);
 403: 				resolve(code ?? 0);
 404: 			});
 405: 
 406: 			proc.on("error", () => {
 407: 				resolve(1);
 408: 			});
 409: 
 410: 			if (signal) {
 411: 				const killProc = () => {
 412: 					wasAborted = true;
 413: 					proc.kill("SIGTERM");
 414: 					setTimeout(() => {
 415: 						if (!proc.killed) proc.kill("SIGKILL");
 416: 					}, 5000);
 417: 				};
 418: 				if (signal.aborted) killProc();
 419: 				else signal.addEventListener("abort", killProc, { once: true });
 420: 			}
 421: 		});
 422: 
 423: 		currentResult.exitCode = exitCode;
 424: 		if (wasAborted) throw new Error("Subagent was aborted");
 425: 		return currentResult;
 426: 	} finally {
 427: 		if (tmpPromptPath)
 428: 			try {
 429: 				fs.unlinkSync(tmpPromptPath);
 430: 			} catch {
 431: 				/* ignore */
 432: 			}
 433: 		if (tmpPromptDir)
 434: 			try {
 435: 				fs.rmdirSync(tmpPromptDir);
 436: 			} catch {
 437: 				/* ignore */
 438: 			}
 439: 	}
 440: }
