 442: const TaskItem = Type.Object({
 443: 	agent: Type.String({ description: "Name of the agent to invoke" }),
 444: 	task: Type.String({ description: "Task to delegate to the agent" }),
 445: 	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
 446: });
 447: 
 448: const ChainItem = Type.Object({
 449: 	agent: Type.String({ description: "Name of the agent to invoke" }),
 450: 	task: Type.String({ description: "Task with optional {previous} placeholder for prior output" }),
 451: 	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
 452: });
 453: 
 454: const AgentScopeSchema = StringEnum(["user", "project", "both"] as const, {
 455: 	description: 'Which agent directories to use. Default: "user". Use "both" to include project-local agents.',
 456: 	default: "user",
 457: });
 458: 
 459: const SubagentParams = Type.Object({
 460: 	agent: Type.Optional(Type.String({ description: "Name of the agent to invoke (for single mode)" })),
 461: 	task: Type.Optional(Type.String({ description: "Task to delegate (for single mode)" })),
 462: 	tasks: Type.Optional(Type.Array(TaskItem, { description: "Array of {agent, task} for parallel execution" })),
 463: 	chain: Type.Optional(Type.Array(ChainItem, { description: "Array of {agent, task} for sequential execution" })),
 464: 	agentScope: Type.Optional(AgentScopeSchema),
 465: 	confirmProjectAgents: Type.Optional(
 466: 		Type.Boolean({ description: "Prompt before running project-local agents. Default: true.", default: true }),
 467: 	),
 468: 	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process (single mode)" })),
 469: });
 470: 
 471: export default function (pi: ExtensionAPI) {
 472: 	pi.registerTool({
 473: 		name: "subagent",
 474: 		label: "Subagent",
 475: 		description: [
 476: 			"Delegate tasks to specialized subagents with isolated context.",
 477: 			"Modes: single (agent + task), parallel (tasks array), chain (sequential with {previous} placeholder).",
 478: 			`Default agent scope is "user" (from ${path.join(getAgentDir(), "agents")}).`,
 479: 			`To enable project-local agents in ${CONFIG_DIR_NAME}/agents, set agentScope: "both" (or "project").`,
 480: 		].join(" "),
 481: 		parameters: SubagentParams,
 482: 
 483: 		async execute(_toolCallId, params, signal, onUpdate, ctx) {
 484: 			const agentScope: AgentScope = params.agentScope ?? "user";
 485: 			const dispatchDefaults: DispatchDefaults = {
 486: 				model: ctx.model ? `${ctx.model.provider}/${ctx.model.id}` : undefined,
 487: 				thinkingLevel: ctx.thinkingLevel,
 488: 			};
 489: 			const discovery = discoverAgents(ctx.cwd, agentScope);
 490: 			const agents = discovery.agents;
 491: 			const confirmProjectAgents = params.confirmProjectAgents ?? true;
 492: 
 493: 			const hasChain = (params.chain?.length ?? 0) > 0;
 494: 			const hasTasks = (params.tasks?.length ?? 0) > 0;
 495: 			const hasSingle = Boolean(params.agent && params.task);
 496: 			const modeCount = Number(hasChain) + Number(hasTasks) + Number(hasSingle);
 497: 
 498: 			const makeDetails =
 499: 				(mode: "single" | "parallel" | "chain") =>
 500: 				(results: SingleResult[]): SubagentDetails => ({
 501: 					mode,
 502: 					agentScope,
 503: 					projectAgentsDir: discovery.projectAgentsDir,
 504: 					results,
 505: 				});
 506: 
 507: 			if (modeCount !== 1) {
 508: 				const available = agents.map((a) => `${a.name} (${a.source})`).join(", ") || "none";
 509: 				return {
 510: 					content: [
 511: 						{
 512: 							type: "text",
 513: 							text: `Invalid parameters. Provide exactly one mode.\nAvailable agents: ${available}`,
 514: 						},
 515: 					],
 516: 					details: makeDetails("single")([]),
 517: 				};
 518: 			}
 519: 
 520: 			if (
 521: 				(agentScope === "project" || agentScope === "both") &&
 522: 				confirmProjectAgents &&
 523: 				ctx.hasUI &&
 524: 				!ctx.isProjectTrusted()
 525: 			) {
 526: 				const requestedAgentNames = new Set<string>();
 527: 				if (params.chain) for (const step of params.chain) requestedAgentNames.add(step.agent);
 528: 				if (params.tasks) for (const t of params.tasks) requestedAgentNames.add(t.agent);
 529: 				if (params.agent) requestedAgentNames.add(params.agent);
 530: 
 531: 				const projectAgentsRequested = Array.from(requestedAgentNames)
 532: 					.map((name) => agents.find((a) => a.name === name))
 533: 					.filter((a): a is AgentConfig => a?.source === "project");
 534: 
 535: 				if (projectAgentsRequested.length > 0) {
 536: 					const names = projectAgentsRequested.map((a) => a.name).join(", ");
 537: 					const dir = discovery.projectAgentsDir ?? "(unknown)";
 538: 					const ok = await ctx.ui.confirm(
 539: 						"Run project-local agents?",
 540: 						`Agents: ${names}\nSource: ${dir}\n\nProject agents are repo-controlled. Only continue for trusted repositories.`,
 541: 					);
 542: 					if (!ok)
 543: 						return {
 544: 							content: [{ type: "text", text: "Canceled: project-local agents not approved." }],
 545: 							details: makeDetails(hasChain ? "chain" : hasTasks ? "parallel" : "single")([]),
 546: 						};
 547: 				}
 548: 			}
 549: 
 550: 			if (params.chain && params.chain.length > 0) {
 551: 				const results: SingleResult[] = [];
 552: 				let previousOutput = "";
 553: 
 554: 				for (let i = 0; i < params.chain.length; i++) {
 555: 					const step = params.chain[i];
 556: 					const taskWithContext = step.task.replace(/\{previous\}/g, previousOutput);
 557: 
 558: 					// Create update callback that includes all previous results
 559: 					const chainUpdate: OnUpdateCallback | undefined = onUpdate
 560: 						? (partial) => {
 561: 								// Combine completed results with current streaming result
 562: 								const currentResult = partial.details?.results[0];
 563: 								if (currentResult) {
 564: 									const allResults = [...results, currentResult];
 565: 									onUpdate({
 566: 										content: partial.content,
 567: 										details: makeDetails("chain")(allResults),
 568: 									});
 569: 								}
 570: 							}
 571: 						: undefined;
 572: 
 573: 					const result = await runSingleAgent(
 574: 						ctx.cwd,
 575: 						dispatchDefaults,
 576: 						agents,
 577: 						step.agent,
 578: 						taskWithContext,
 579: 						step.cwd,
 580: 						i + 1,
 581: 						signal,
 582: 						chainUpdate,
 583: 						makeDetails("chain"),
 584: 					);
 585: 					results.push(result);
 586: 
 587: 					const isError = isFailedResult(result);
 588: 					if (isError) {
 589: 						const errorMsg = getResultOutput(result);
 590: 						return {
 591: 							content: [{ type: "text", text: `Chain stopped at step ${i + 1} (${step.agent}): ${errorMsg}` }],
 592: 							details: makeDetails("chain")(results),
 593: 							isError: true,
 594: 						};
 595: 					}
 596: 					previousOutput = getFinalOutput(result.messages);
 597: 				}
 598: 				return {
 599: 					content: [{ type: "text", text: getFinalOutput(results[results.length - 1].messages) || "(no output)" }],
 600: 					details: makeDetails("chain")(results),
 601: 				};
 602: 			}
 603: 
 604: 			if (params.tasks && params.tasks.length > 0) {
 605: 				if (params.tasks.length > MAX_PARALLEL_TASKS)
 606: 					return {
 607: 						content: [
 608: 							{
 609: 								type: "text",
 610: 								text: `Too many parallel tasks (${params.tasks.length}). Max is ${MAX_PARALLEL_TASKS}.`,
 611: 							},
 612: 						],
 613: 						details: makeDetails("parallel")([]),
 614: 					};
 615: 
 616: 				// Track all results for streaming updates
 617: 				const allResults: SingleResult[] = new Array(params.tasks.length);
 618: 
 619: 				// Initialize placeholder results
 620: 				for (let i = 0; i < params.tasks.length; i++) {
 621: 					allResults[i] = {
 622: 						agent: params.tasks[i].agent,
 623: 						agentSource: "unknown",
