   1: /**
   2:  * Subagent Tool - Delegate tasks to specialized agents
   3:  *
   4:  * Spawns a separate `pi` process for each subagent invocation,
   5:  * giving it an isolated context window.
   6:  *
   7:  * Supports three modes:
   8:  *   - Single: { agent: "name", task: "..." }
   9:  *   - Parallel: { tasks: [{ agent: "name", task: "..." }, ...] }
  10:  *   - Chain: { chain: [{ agent: "name", task: "... {previous} ..." }, ...] }
  11:  *
  12:  * Uses JSON mode to capture structured output from subagents.
  13:  */
  14: 
  15: import { spawn } from "node:child_process";
  16: import * as fs from "node:fs";
  17: import * as os from "node:os";
  18: import * as path from "node:path";
  19: import type { AgentToolResult, ThinkingLevel } from "@earendil-works/pi-agent-core";
  20: import type { Message } from "@earendil-works/pi-ai";
  21: import { StringEnum } from "@earendil-works/pi-ai";
  22: import {
  23: 	CONFIG_DIR_NAME,
  24: 	type ExtensionAPI,
  25: 	getAgentDir,
  26: 	getMarkdownTheme,
  27: 	withFileMutationQueue,
  28: } from "@earendil-works/pi-coding-agent";
  29: import { Container, Markdown, Spacer, Text } from "@earendil-works/pi-tui";
  30: import { Type } from "typebox";
  31: import { type AgentConfig, type AgentScope, discoverAgents } from "./agents.ts";
  32: 
  33: const MAX_PARALLEL_TASKS = 8;
  34: const MAX_CONCURRENCY = 4;
  35: const COLLAPSED_ITEM_COUNT = 10;
  36: const PER_TASK_OUTPUT_CAP = 50 * 1024;
  37: 
  38: function formatTokens(count: number): string {
  39: 	if (count < 1000) return count.toString();
  40: 	if (count < 10000) return `${(count / 1000).toFixed(1)}k`;
  41: 	if (count < 1000000) return `${Math.round(count / 1000)}k`;
  42: 	return `${(count / 1000000).toFixed(1)}M`;
  43: }
