 182: function isFailedResult(result: SingleResult): boolean {
 183: 	return result.exitCode !== 0 || result.stopReason === "error" || result.stopReason === "aborted";
 184: }
 185: 
 186: function getResultOutput(result: SingleResult): string {
 187: 	if (isFailedResult(result)) {
 188: 		return result.errorMessage || result.stderr || getFinalOutput(result.messages) || "(no output)";
 189: 	}
 190: 	return getFinalOutput(result.messages) || "(no output)";
 191: }
