 193: function truncateParallelOutput(output: string): string {
 194: 	const byteLength = Buffer.byteLength(output, "utf8");
 195: 	if (byteLength <= PER_TASK_OUTPUT_CAP) return output;
 196: 
 197: 	let truncated = output.slice(0, PER_TASK_OUTPUT_CAP);
 198: 	while (Buffer.byteLength(truncated, "utf8") > PER_TASK_OUTPUT_CAP) {
 199: 		truncated = truncated.slice(0, -1);
 200: 	}
 201: 	return `${truncated}\n\n[Output truncated: ${byteLength - Buffer.byteLength(truncated, "utf8")} bytes omitted. Full output preserved in tool details.]`;
 202: }
