 239: async function writePromptToTempFile(agentName: string, prompt: string): Promise<{ dir: string; filePath: string }> {
 240: 	const tmpDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), "pi-subagent-"));
 241: 	const safeName = agentName.replace(/[^\w.-]+/g, "_");
 242: 	const filePath = path.join(tmpDir, `prompt-${safeName}.md`);
 243: 	await withFileMutationQueue(filePath, async () => {
 244: 		await fs.promises.writeFile(filePath, prompt, { encoding: "utf-8", mode: 0o600 });
 245: 	});
 246: 	return { dir: tmpDir, filePath };
 247: }
