 442: const TaskItem = Type.Object({
 443: 	agent: Type.String({ description: "Name of the agent to invoke" }),
 444: 	task: Type.String({ description: "Task to delegate to the agent" }),
 445: 	cwd: Type.Optional(Type.String({ description: "Working directory for the agent process" })),
 446: });
