5414:     async handleBashCommand(command, excludeFromContext = false) {
5415:         const extensionRunner = this.session.extensionRunner;
5416:         // Emit user_bash event to let extensions intercept
5417:         const eventResult = await extensionRunner.emitUserBash({
5418:             type: "user_bash",
5419:             command,
5420:             excludeFromContext,
5421:             cwd: this.sessionManager.getCwd(),
5422:         });
5423:         // If extension returned a full result, use it directly
5424:         if (eventResult?.result) {
5425:             const result = eventResult.result;
5426:             // Create UI component for display
5427:             this.bashComponent = new BashExecutionComponent(command, this.ui, excludeFromContext);
5428:             if (this.session.isStreaming) {
5429:                 this.pendingMessagesContainer.addChild(this.bashComponent);
5430:                 this.pendingBashComponents.push(this.bashComponent);
5431:             }
5432:             else {
5433:                 this.chatContainer.addChild(this.bashComponent);
5434:             }
5435:             // Show output and complete
5436:             if (result.output) {
5437:                 this.bashComponent.appendOutput(result.output);
5438:             }
5439:             this.bashComponent.setComplete(result.exitCode, result.cancelled, result.truncated ? { truncated: true, content: result.output } : undefined, result.fullOutputPath);
5440:             // Record the result in session
5441:             this.session.recordBashResult(command, result, { excludeFromContext });
5442:             this.bashComponent = undefined;
5443:             this.ui.requestRender();
5444:             return;
5445:         }
5446:         // Normal execution path (possibly with custom operations)
5447:         const isDeferred = this.session.isStreaming;
5448:         this.bashComponent = new BashExecutionComponent(command, this.ui, excludeFromContext);
5449:         if (isDeferred) {
5450:             // Show in pending area when agent is streaming
5451:             this.pendingMessagesContainer.addChild(this.bashComponent);
5452:             this.pendingBashComponents.push(this.bashComponent);
5453:         }
5454:         else {
5455:             // Show in chat immediately when agent is idle
5456:             this.chatContainer.addChild(this.bashComponent);
5457:         }
5458:         this.ui.requestRender();
5459:         try {
5460:             const result = await this.session.executeBash(command, (chunk) => {
5461:                 if (this.bashComponent) {
5462:                     this.bashComponent.appendOutput(chunk);
5463:                     this.ui.requestRender();
5464:                 }
5465:             }, { excludeFromContext, operations: eventResult?.operations });
5466:             if (this.bashComponent) {
5467:                 this.bashComponent.setComplete(result.exitCode, result.cancelled, result.truncated ? { truncated: true, content: result.output } : undefined, result.fullOutputPath);
5468:             }

