    self.returncode = 0
    self.terminated = False
    self.killed = False
    self.calls = 0

def communicate(self, timeout=None):
    self.calls += 1
    if self.killed:
        return ("", "")  # kill 生效后正常返回（模拟进程已死）
    if self.sticky_terminate:
        # 模拟 terminate 无效：communicate 始终超时（触发 kill 兜底）
        raise subprocess.TimeoutExpired("pi", timeout)
    if self.behavior == "ok":
        return ("OUT", "ERR")

