import json
f = r"$F"
lines = open(f).readlines()
# 关键判断：12:22:04（分析启动）之后，这个 agent 自己（非同步自我的命令）有哪些动作？
# 方法：找 parentId 链——wake user entry 的 id，然后顺着链走
wake_id = None
for i, l in enumerate(lines):
    try: e = json.loads(l)
    except: continue
    if e.get('type')=='message':
        m = e.get('message', {})
        c = m.get('content')
        txt = c if isinstance(c,str) else ''.join(x.get('text','') for x in (c or []) if isinstance(x,dict) and x.get('type')=='text')
        if m.get('role')=='user' and '行为纪律' in txt:
            wake_id = e.get('id'); wake_ts = (e.get('timestamp') or '')[11:19]
            print(f'wake entry: id={wake_id} ts={wake_ts} index={i}')
            break
# 沿 parent 链走
if wake_id:
    by_id = {}
    for l in lines:
        try: e = json.loads(l)
        except: continue
        by_id[e.get('id')] = e
    chain = []
    cur = wake_id
    while cur:
        e = by_id.get(cur)
        if not e: break
        t = e.get('type')
        if t == 'message':
            m = e.get('message', {})
            role = m.get('role')
            c = m.get('content')
            desc = ''
            if isinstance(c, list):
                for x in c:
                    if isinstance(x,dict) and x.get('type')=='toolCall':
                        call = x.get('call') or {}
                        arg = (call.get('arguments') or {}).get('command','')
                        desc = f"TOOL {call.get('name')}: {arg[:100]}"
                        break
                else:
                    txt = ''.join(x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text')
                    desc = f"TEXT: {txt[:100]}"
            elif isinstance(c, str):
                desc = f"USR: {c[:100]}"
            chain.append(f"{(e.get('timestamp') or '')[11:19]} [{role}] {desc}")
        cur = e.get('parentId')
    print('wake 起的链（新→旧，前 15 条）:')
    for c in chain[:15]:
        print(' ', c)
